CREATE DATABASE IF NOT EXISTS support_ticket_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE support_ticket_db;
CREATE TABLE IF NOT EXISTS customers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_customer_name(name),INDEX idx_customer_email(email));
CREATE TABLE IF NOT EXISTS agents(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,department VARCHAR(100) NOT NULL,status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_agent_status(status));
CREATE TABLE IF NOT EXISTS tickets(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,agent_id INT NULL,subject VARCHAR(255) NOT NULL,description TEXT NOT NULL,priority ENUM('LOW','MEDIUM','HIGH','CRITICAL') NOT NULL,category ENUM('TECHNICAL','BILLING','ACCOUNT','GENERAL') NOT NULL,status ENUM('OPEN','IN_PROGRESS','RESOLVED','CLOSED') NOT NULL DEFAULT 'OPEN',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_ticket_customer FOREIGN KEY(customer_id) REFERENCES customers(id),CONSTRAINT fk_ticket_agent FOREIGN KEY(agent_id) REFERENCES agents(id) ON DELETE SET NULL,INDEX idx_ticket_status(status),INDEX idx_ticket_priority(priority),INDEX idx_ticket_category(category),INDEX idx_ticket_agent(agent_id),INDEX idx_ticket_created(created_at),INDEX idx_ticket_subject(subject));
